S=/private/tmp/claude-501/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/scratchpad; mkdir -p $S/rev13/cases; cat > $S/rev13/cases/ex.py <<'EOF'
import re,sys
def blocks(path):
    lines=open(path).read().split('\n')
    out=[];cur=None
    top=re.compile(r'^(example|theorem|def|lemma|instance|/-|/-!|section|end|namespace|open|private|@\[|abbrev|structure|inductive|noncomputable|variable|#)')
    for i,l in enumerate(lines):
        if top.match(l):
            if cur: out.append(cur)
            cur=None
            if l.startswith('example'):
                cur=[i+1,[l]]
        elif cur is not None:
            if l.strip()=='' : out.append(cur); cur=None
            else: cur[1].append(l)
    if cur: out.append(cur)
    return [(n,'\n'.join(b)) for n,b in out]
a=blocks(sys.argv[1]); b=blocks(sys.argv[2])
print(len(a),len(b))
sa={t for _,t in a}; sb={t for _,t in b}
print('unchanged',len([t for _,t in a if t in sb]))
print('--- p5 only')
for n,t in a:
    if t not in sb: print(n, t.replace('\n',' | ')[:220])
print('--- p6 new count', len([t for _,t in b if t not in sa]))
EOF
python3 -I $S/rev13/cases/ex.py $S/p6/p5.lean Ern/MM03.lean

